namespace Customize\Repository;

use Doctrine\Persistence\ManagerRegistry as RegistryInterface;
use Eccube\Entity\ProductCategory;
use Customize\Entity\Shop;
/**
 * ProductCategoryRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class ProductCategoryRepository extends \Eccube\Repository\ProductCategoryRepository
{
    public function __construct(RegistryInterface $registry)
    {
        parent::__construct($registry);
    }


    public function getCategoryByShop(Shop $Shop): array
    {


        $qb = $this->createQueryBuilder('pc')
                   ->innerJoin('pc.Product', 'p')
                   ->innerJoin('pc.Category','c1')
                   ->orderBy('c1.hierarchy', 'ASC')
                    ->addOrderBy('c1.sort_no', 'DESC')
                    ->where('p.Shop = :Shop')
                    ->setParameter('Shop',$Shop);

        $Pcs = $qb->getQuery()->getResult();


        $Re =[];

        foreach ($Pcs as $PC){
            $Category = $PC->getCategory();
            $Re[$Category->getId()] = $Category;
            }

        return $Re ;     

    }

 }
